meta.script:
function getTargetUrl(){
	var targetUrl = "https://www.ibm.com/";
	var ref = document.referrer;
	if(getQuerystring("Target") !==""){
		targetUrl = decodeURIComponent(getQuerystring("Target"));
	}else if(ref){
		targetUrl = document.referrer;
	}
	return targetUrl;
}
function getIdParam(){
	var queryString ="",id=getQuerystring("Id");
	if(id && !(/[<>;"()]/i.test(decodeURIComponent(id)))){
		queryString ="&Id="+id;
	}
	var login_hint=getQuerystring("login_hint");
	if(login_hint && !(/[<>;"()]/i.test(decodeURIComponent(login_hint)))){
		queryString +="&login_hint="+login_hint;
	}
	return queryString;
}
function getQuerystring(key)
{
	key = key.replace(/[\[]/,"\\\[").replace(/[\]]/,"\\\]");
	var regex = new RegExp("[\\?&]"+key+"=([^&#]*)");
	var qs = regex.exec(window.location.href);
	if(qs == null)
		return "";
	else
		return qs[1];
}
function setTargetUrl() {
	var targetUrl = getTargetUrl();
	var cookieName = 'idaasRedirectUrl';
	document.cookie = cookieName +"=" + targetUrl + ";path=/";
}
function setClientIdInCookie() {
	var clientId = getQuerystring('client_id');
	if (clientId){
		document.cookie = "iisvcid=" + clientId + ";path=/";
	}
}
function oidcTargetUrlQueryParam(){
	if(getQuerystring("Target") !==""){
		return "&Target=" + getQuerystring("Target");
	}else{
		return ""
	}
}
function setPromptLoginFlag(){
	try {
		if(getQuerystring("prompt")){
			sessionStorage.setItem('prompt', getQuerystring("prompt"))
		}else if(sessionStorage.getItem('prompt')){
			sessionStorage.removeItem('prompt')
		}
	}catch (e) {
		console.error('Session storage not supported. prompt login won\'t work');
	}

}
setTargetUrl();
setClientIdInCookie();
setPromptLoginFlag();
window.location.href="https://"+window.location.host+"/authsvc/mtfim/sps/authsvc?PolicyId=urn:ibm:security:authentication:asf:basicldapuser"+getIdParam()+oidcTargetUrlQueryParam();
